-- Wave 1: additive, private owner library and campaign foundations. No seeding/network.
begin;
create table rpg_private.library_records (
 owner_id uuid not null references auth.users(id), kind text not null check(kind in ('source','pack','scenario','divergence','compiler_job')),
 id uuid not null, version_id uuid primary key, version integer not null check(version>0), previous_version_id uuid references rpg_private.library_records(version_id),
 body jsonb not null check(jsonb_typeof(body)='object' and octet_length(body::text)<=1048576), created_at timestamptz not null default now(),
 unique(owner_id,kind,id,version)
);
create table rpg_private.library_commands (
 id uuid primary key, owner_id uuid not null references auth.users(id), request jsonb not null, result jsonb not null
);
create table rpg_private.world_foundations (
 campaign_id uuid primary key references public.rpg_campaigns(id) deferrable initially deferred,
 revision integer not null default 1 check(revision>0), world jsonb,
 bindings jsonb not null default '[]', ruleset jsonb not null default '{"id":"console-basic-v1","version":1,"mode":"full_ruleset","validatorVersion":"console-basic-v1"}',
 execution_policy jsonb
);
create table rpg_private.world_events (
 id uuid primary key, campaign_id uuid not null references public.rpg_campaigns(id) deferrable initially deferred,
 operation_id uuid not null, sequence bigint generated by default as identity, event jsonb not null,
 foreign key(campaign_id,operation_id) references rpg_private.turns(campaign_id,id) deferrable initially deferred
);
create table rpg_private.world_stages (
 id uuid primary key, campaign_id uuid not null references public.rpg_campaigns(id) deferrable initially deferred,
 settlement jsonb not null,
 foreign key(campaign_id,id) references rpg_private.turns(campaign_id,id) deferrable initially deferred
);
create table rpg_private.world_commands (
 id uuid primary key, campaign_id uuid not null references public.rpg_campaigns(id) deferrable initially deferred,
 request jsonb not null, result jsonb not null
);
create table rpg_private.execution_profiles (
 id uuid primary key, campaign_id uuid not null references public.rpg_campaigns(id) deferrable initially deferred,
 operation_id uuid not null, task text not null, profile jsonb not null, unique(campaign_id,operation_id,task)
);
-- Immutable owner history is never part of campaign rollback.
create trigger immutable_library_record before update or delete on rpg_private.library_records for each row execute function rpg_private.timeline_immutable();
create trigger immutable_library_command before update or delete on rpg_private.library_commands for each row execute function rpg_private.timeline_immutable();
-- Extend the existing save engine, preserving the exact v1 family inventory.
alter function rpg_private.timeline_tables() rename to timeline_tables_v1;
create function rpg_private.timeline_tables() returns text[] language sql immutable set search_path='' as $$
 select rpg_private.timeline_tables_v1()||array['rpg_private.world_foundations','rpg_private.world_events','rpg_private.world_stages','rpg_private.world_commands','rpg_private.execution_profiles']::text[]
$$;
alter table rpg_private.timeline_manifests alter column schema_version set default 2;
-- Same immutable manifest/hash/canon checks; family inventory selected by stored version.
do $$ declare d text; begin
 select pg_get_functiondef('rpg_private.timeline_validate(uuid,uuid)'::regprocedure) into d;
 d:=replace(d,'m.schema_version<>1','m.schema_version not in (1,2)');
 d:=replace(d,'rpg_private.timeline_tables()','(case when m.schema_version=1 then rpg_private.timeline_tables_v1() else rpg_private.timeline_tables() end)');
 execute d;
end $$;
do $$ declare t text; begin
 foreach t in array array['library_records','library_commands','world_foundations','world_events','world_stages','world_commands','execution_profiles'] loop
  execute format('alter table rpg_private.%I enable row level security',t);
 end loop;
 foreach t in array array['world_events','world_stages','world_commands','execution_profiles'] loop
  execute format('create trigger immutable_world_history before update or delete on rpg_private.%I for each row execute function rpg_private.immutable_history()',t);
 end loop;
end $$;
create function rpg_private.library_record_json(r rpg_private.library_records) returns jsonb language sql immutable set search_path='' as $$
 select jsonb_build_object('schemaVersion',1,'ownerId',r.owner_id,'kind',r.kind,'id',r.id,'versionId',r.version_id,'version',r.version,'previousVersionId',r.previous_version_id,'body',r.body)
$$;
create function rpg_private.library_ref(uid uuid, vid text, k text) returns jsonb language plpgsql stable set search_path='' as $$
#variable_conflict use_column
declare r rpg_private.library_records%rowtype; begin
 select * into r from rpg_private.library_records where owner_id=uid and version_id=vid::uuid and kind=k;
 if not found then raise exception 'rpg_validation'; end if;
 return rpg_private.library_record_json(r);
end $$;
create function rpg_private.uuid_array(v jsonb, maximum integer default 500) returns void language plpgsql immutable set search_path='' as $$
begin
 perform rpg_private.assert(jsonb_typeof(v)='array' and jsonb_array_length(v)<=maximum);
 perform rpg_private.assert(not exists(select 1 from jsonb_array_elements(v) x where jsonb_typeof(x)<>'string' or (x#>>'{}')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'));
 perform rpg_private.assert((select count(*)=count(distinct value) from jsonb_array_elements_text(v)));
end $$;
create function rpg_private.source_set(uid uuid, sources jsonb, priority jsonb) returns void language plpgsql stable set search_path='' as $$
#variable_conflict use_column
declare v text; begin
 perform rpg_private.uuid_array(sources); perform rpg_private.uuid_array(priority);
 perform rpg_private.assert(sources@>priority and priority@>sources);
 for v in select jsonb_array_elements_text(sources) loop perform rpg_private.library_ref(uid,v,'source'); end loop;
end $$;
create function rpg_private.library_evidence(uid uuid, evidence jsonb, allowed jsonb, public_only boolean default false) returns void language plpgsql stable set search_path='' as $$
#variable_conflict use_column
declare e jsonb; s jsonb; begin
 perform rpg_private.assert(jsonb_typeof(evidence)='array' and jsonb_array_length(evidence)<=100);
 for e in select value from jsonb_array_elements(evidence) loop
  perform rpg_private.fields(e,array['ownerId','sourceId','sourceVersionId','locator','digest','visibility','knowledge']);
  s:=rpg_private.library_ref(uid,e->>'sourceVersionId','source');
  perform rpg_private.assert(e->>'ownerId'=uid::text and e->>'sourceId'=s->>'id' and allowed ? (e->>'sourceVersionId') and e->>'digest'=s#>>'{body,digest}');
  perform rpg_private.assert(e->>'visibility' in ('public','private') and e->>'knowledge' in ('source','canon_at_entry','character','future_source'));
  perform rpg_private.fields(e->'locator',array['kind','value']);
  perform rpg_private.assert(e#>>'{locator,kind}' in ('text','page','section','image') and length(e#>>'{locator,value}') between 1 and 2000);
  if e->>'visibility'='public' then perform rpg_private.assert(s#>>'{body,visibility}'='public'); end if;
  if public_only then perform rpg_private.assert(e->>'visibility'='public' and e->>'knowledge' in ('canon_at_entry','character')); end if;
 end loop;
end $$;
create function public.rpg_library(p_owner_id uuid,p_campaign_id uuid,p_action text,p_payload jsonb default '{}',p_timeline jsonb default null) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare r jsonb; b jsonb; old rpg_private.library_records%rowtype; saved rpg_private.library_commands%rowtype; ref jsonb; v text; e jsonb; cid uuid; ev record; result jsonb; op uuid; state_order text[]:=array['queued','extracting','indexing','auditing','awaiting_review','completed']; begin
 if p_owner_id is null or not exists(select 1 from rpg_private.owner_registry where user_id=p_owner_id) then raise exception 'rpg_forbidden' using errcode='42501'; end if;
 perform rpg_private.assert(p_campaign_id is null and p_timeline is null);
 if p_action='read' then
  perform rpg_private.fields(p_payload,'{}',array['kind','id','versionId']);
  select coalesce(jsonb_agg(rpg_private.library_record_json(x) order by x.kind,x.id,x.version),'[]') into result from
   (select * from rpg_private.library_records where owner_id=p_owner_id and (not p_payload?'kind' or kind=p_payload->>'kind') and (not p_payload?'id' or id=(p_payload->>'id')::uuid) and (not p_payload?'versionId' or version_id=(p_payload->>'versionId')::uuid) order by kind,id,version limit 501) x;
  perform rpg_private.assert(jsonb_array_length(result)<=500); return jsonb_build_object('records',result);
 end if;
 perform rpg_private.assert(p_action='put'); perform rpg_private.fields(p_payload,array['operationId','record']);
 op:=(p_payload->>'operationId')::uuid; r:=p_payload->'record'; b:=r->'body';
 perform 1 from rpg_private.owner_registry where user_id=p_owner_id for update;
 select * into saved from rpg_private.library_commands where id=op;
 if found then if saved.owner_id<>p_owner_id or saved.request<>p_payload then raise exception 'rpg_conflict'; end if; return saved.result; end if;
 perform rpg_private.fields(r,array['schemaVersion','ownerId','kind','id','versionId','version','previousVersionId','body']);
 perform rpg_private.assert(r->>'ownerId'=p_owner_id::text and r->>'schemaVersion'='1' and b->>'schemaVersion'='1' and octet_length(b::text)<=1048576);
 select * into old from rpg_private.library_records where owner_id=p_owner_id and kind=r->>'kind' and id=(r->>'id')::uuid order by version desc limit 1;
 if found then perform rpg_private.assert((r->>'version')::integer=old.version+1 and r->>'previousVersionId'=old.version_id::text);
 else perform rpg_private.assert(r->>'version'='1' and r->'previousVersionId'='null'); end if;
 if r->>'kind' in ('pack','scenario','compiler_job') then perform rpg_private.source_set(p_owner_id,b->'sourceVersionIds',b->'sourcePriority'); end if;
 if r->>'kind'='source' then
  perform rpg_private.assert(b->>'visibility' in ('public','private') and b->>'digest' ~ '^[0-9a-f]{64}$');
  if b#>>'{original,kind}'='text' then perform rpg_private.assert(b->>'digest'=encode(sha256(convert_to(b#>>'{original,text}','UTF8')),'hex'));
  else perform rpg_private.assert(b#>>'{original,kind}'='storage' and b#>>'{original,bucket}'='world-sources' and b#>>'{original,path}' like p_owner_id::text||'/'||(r->>'id')||'/'||(r->>'versionId')||'/%' and b#>>'{original,path}' !~ '(\.\.|%|\\|:)' and (b#>>'{original,byteLength}')::bigint between 1 and 1073741824); end if;
 elsif r->>'kind'='pack' then
  if b->>'compilerJobVersionId' is not null then ref:=rpg_private.library_ref(p_owner_id,b->>'compilerJobVersionId','compiler_job'); perform rpg_private.assert(ref#>>'{body,targetPackId}'=r->>'id' and ref#>'{body,sourceVersionIds}'=b->'sourceVersionIds'); end if;
  for e in select value from jsonb_array_elements(b->'claims') loop
   perform rpg_private.library_evidence(p_owner_id,e->'evidence',b->'sourceVersionIds',e->>'visibility'='public' and e->>'knowledge' in ('canon_at_entry','character'));
   perform rpg_private.assert(e->>'origin' in ('source_fact','source_inference','scenario_assumption'));
  end loop;
 elsif r->>'kind'='scenario' then
  perform rpg_private.uuid_array(b->'packVersionIds'); result:='[]';
  for v in select jsonb_array_elements_text(b->'packVersionIds') loop ref:=rpg_private.library_ref(p_owner_id,v,'pack'); result:=result||(ref#>'{body,sourceVersionIds}'); end loop;
  perform rpg_private.assert(result@>(b->'sourceVersionIds') and (b->'sourceVersionIds')@>result);
  perform rpg_private.library_evidence(p_owner_id,b#>'{entry,evidence}',b->'sourceVersionIds');
 elsif r->>'kind'='divergence' then perform rpg_private.library_ref(p_owner_id,b->>'scenarioVersionId','scenario');
 elsif r->>'kind'='compiler_job' then
  perform rpg_private.assert(b->>'status'=any(state_order||array['failed','invalidated']) and jsonb_typeof(b->'checkpoints')='array');
  if old.id is null then perform rpg_private.assert(b->>'status'='queued' and b->'checkpoints'='[]');
  else
   perform rpg_private.assert(old.body->>'status' not in ('failed','invalidated'));
   perform rpg_private.assert((b-array['status','checkpoints','errorCode'])=(old.body-array['status','checkpoints','errorCode']));
   perform rpg_private.assert((b->>'status'='invalidated') or (b->>'status'='failed' and old.body->>'status'<>'completed') or (old.body->>'status'<>'completed' and array_position(state_order,b->>'status') between array_position(state_order,old.body->>'status') and array_position(state_order,old.body->>'status')+1));
   perform rpg_private.assert(jsonb_array_length(b->'checkpoints')>=jsonb_array_length(old.body->'checkpoints') and not exists(select 1 from jsonb_array_elements(old.body->'checkpoints') with ordinality x(val,n) where b->'checkpoints'->(n::integer-1)<>val));
  end if;
 end if;
 insert into rpg_private.library_records(owner_id,kind,id,version_id,version,previous_version_id,body) values(p_owner_id,r->>'kind',(r->>'id')::uuid,(r->>'versionId')::uuid,(r->>'version')::integer,(r->>'previousVersionId')::uuid,b);
 -- A source revision does not repin or rewrite any campaign. Invalidate dependent derivative work.
 if r->>'kind'='source' and old.id is not null then
  for cid in select distinct f.campaign_id from rpg_private.world_foundations f,jsonb_array_elements(f.bindings) x where exists(select 1 from jsonb_array_elements_text(x->'sourceVersionIds') s join rpg_private.library_records z on z.version_id=s::uuid where z.owner_id=p_owner_id and z.id=old.id and z.kind='source') loop
   update rpg_private.world_foundations set revision=revision+1 where campaign_id=cid;
   update rpg_private.runtime_state set revision=revision+1 where campaign_id=cid;
   update rpg_private.timeline_campaigns set canon_generation=canon_generation+1 where campaign_id=cid;
   for ev in select w.id from rpg_private.world_events w where w.campaign_id=cid and exists(select 1 from jsonb_array_elements(w.event->'evidence') e where e->>'sourceId'=old.id::text) loop perform rpg_private.memory_restrict_source(cid,'event',ev.id); end loop;
   perform rpg_private.world_invalidate_derivatives(cid);
   perform rpg_private.memory_invalidate(cid);
  end loop;
 end if;
 insert into rpg_private.library_commands values(op,p_owner_id,p_payload,r); return r;
end $$;
create function rpg_private.foundation_read(uid uuid,cid uuid) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('schemaVersion',1,'ownerId',uid,'campaignId',cid,'timeline',rpg_private.timeline_fence(cid),
 'revision',coalesce(f.revision,0),'runtimeRevision',r.revision,'headId',t.head_manifest_id,'worldMinutes',r.world_minutes,
 'world',f.world,'bindings',coalesce(f.bindings,'[]'),'ruleset',coalesce(f.ruleset,'{"id":"console-basic-v1","version":1,"mode":"full_ruleset","validatorVersion":"console-basic-v1"}'::jsonb),'executionPolicy',f.execution_policy)
 from rpg_private.runtime_state r join rpg_private.timeline_campaigns tc on tc.campaign_id=r.campaign_id join rpg_private.timelines t on t.campaign_id=tc.campaign_id and t.id=tc.active_timeline_id left join rpg_private.world_foundations f on f.campaign_id=r.campaign_id where r.campaign_id=cid
$$;
create function rpg_private.foundation_fence(uid uuid,cid uuid,command jsonb) returns jsonb language plpgsql stable set search_path='' as $$
#variable_conflict use_column
declare snapshot jsonb; begin
 snapshot:=rpg_private.foundation_read(uid,cid);
 if snapshot is null or command->>'campaignId' is distinct from cid::text or command->'timeline' is distinct from snapshot->'timeline' or command->'expectedRevision' is distinct from snapshot->'revision' or command->'expectedRuntimeRevision' is distinct from snapshot->'runtimeRevision' or command->'expectedHeadId' is distinct from snapshot->'headId' then raise exception 'rpg_conflict'; end if;
 return snapshot;
end $$;
create function public.rpg_world(p_owner_id uuid,p_campaign_id uuid,p_action text,p_payload jsonb default '{}',p_timeline jsonb default null) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare command jsonb; snap jsonb; binding jsonb; pack jsonb; scenario jsonb; pack_sources jsonb; pack_entities jsonb; candidate jsonb; pv text; v jsonb; result jsonb; saved rpg_private.world_commands%rowtype; op uuid; w jsonb; actor jsonb; cid uuid:=p_campaign_id; sources jsonb; turn rpg_private.turns%rowtype; begin
 if p_owner_id is null or not exists(select 1 from rpg_private.owner_registry where user_id=p_owner_id) then raise exception 'rpg_forbidden' using errcode='42501'; end if;
 perform 1 from public.rpg_campaigns where id=cid for update; if not found then raise exception 'rpg_not_found'; end if;
 perform rpg_private.timeline_assert(cid,p_timeline,p_action<>'read');
 if p_action='read' then perform rpg_private.fields(p_payload,'{}'); return rpg_private.foundation_read(p_owner_id,cid); end if;
 command:=p_payload->'command'; op:=(command->>'operationId')::uuid;
 perform rpg_private.fields(command,array['operationId','campaignId','timeline','expectedRevision','expectedRuntimeRevision','expectedHeadId']);
 if command->'timeline' is distinct from p_timeline then raise exception 'rpg_conflict'; end if;
 select * into saved from rpg_private.world_commands where id=op;
 if found then if saved.campaign_id<>cid or saved.request<>jsonb_build_object('action',p_action,'payload',p_payload) then raise exception 'rpg_conflict'; end if; return saved.result; end if;
 if exists(select 1 from rpg_private.timeline_command_ids where category='world' and id=op) then raise exception 'rpg_conflict'; end if;
 snap:=rpg_private.foundation_fence(p_owner_id,cid,command);
 if p_action='stage' then
  perform rpg_private.fields(p_payload,array['command','settlement']); result:=p_payload->'settlement';
  perform rpg_private.assert((result-array['schemaVersion','status','fromWorldMinutes','throughWorldMinutes','sourceVersionIds','events','nextWorld'])=command);
  select * into turn from rpg_private.turns where campaign_id=cid and id=op;
  perform rpg_private.assert(turn.id is not null and turn.status='generating' and turn.expected_revision=(snap->>'runtimeRevision')::integer and turn.input->>'mode' in ('game','mechanic','companion'));
  perform rpg_private.world_validate_settlement(p_owner_id,cid,result,turn);
  insert into rpg_private.world_stages(id,campaign_id,settlement) values(op,cid,result);
 elsif p_action='bind' then
  perform rpg_private.fields(p_payload,array['command','binding']); binding:=p_payload->'binding';
  perform rpg_private.fields(binding,array['schemaVersion','id','campaignId','ownerId','packId','packVersionId','scenarioVersionId','sourceVersionIds','sourcePriority','entry','mappings']);
  perform rpg_private.assert(binding->>'schemaVersion'='1' and binding->>'campaignId'=cid::text and binding->>'ownerId'=p_owner_id::text);
  pack:=rpg_private.library_ref(p_owner_id,binding->>'packVersionId','pack');
  perform rpg_private.assert(pack->>'id'=binding->>'packId' and pack#>>'{body,status}'='approved');
  pack_sources:=pack#>'{body,sourceVersionIds}'; pack_entities:=pack#>'{body,entities}';
  if binding->>'scenarioVersionId' is not null then
   scenario:=rpg_private.library_ref(p_owner_id,binding->>'scenarioVersionId','scenario');
   perform rpg_private.assert(scenario#>>'{body,status}'='approved' and scenario#>'{body,packVersionIds}' ? (binding->>'packVersionId') and scenario#>'{body,entry}'=binding->'entry' and scenario#>'{body,sourcePriority}'=binding->'sourcePriority');
   pack_sources:='[]';pack_entities:='[]';
   for pv in select jsonb_array_elements_text(scenario#>'{body,packVersionIds}') loop
    candidate:=rpg_private.library_ref(p_owner_id,pv,'pack');perform rpg_private.assert(candidate#>>'{body,status}'='approved');
    pack_sources:=pack_sources||(candidate#>'{body,sourceVersionIds}');pack_entities:=pack_entities||(candidate#>'{body,entities}');
   end loop;
  end if;
  perform rpg_private.assert(pack_sources@>(binding->'sourceVersionIds') and (binding->'sourceVersionIds')@>pack_sources);
  perform rpg_private.source_set(p_owner_id,binding->'sourceVersionIds',binding->'sourcePriority');
  perform rpg_private.library_evidence(p_owner_id,binding#>'{entry,evidence}',binding->'sourceVersionIds');
  perform rpg_private.assert((binding#>>'{entry,worldMinutes}')::bigint>=0 and length(binding#>>'{entry,label}') between 1 and 200);
  if binding->>'scenarioVersionId' is not null then scenario:=rpg_private.library_ref(p_owner_id,binding->>'scenarioVersionId','scenario'); perform rpg_private.assert(scenario#>>'{body,status}'='approved' and scenario#>'{body,packVersionIds}' ? (binding->>'packVersionId')); end if;
  perform rpg_private.assert(jsonb_array_length(binding->'mappings')=jsonb_array_length(pack_entities));
  perform rpg_private.assert(jsonb_typeof(binding->'mappings')='array' and jsonb_array_length(binding->'mappings')<=500 and (select count(*)=count(distinct value->>'packEntityId') and count(*)=count(distinct value->>'entityId') from jsonb_array_elements(binding->'mappings')));
  for v in select value from jsonb_array_elements(binding->'mappings') loop
   perform rpg_private.assert(exists(select 1 from jsonb_array_elements(pack_entities) e where e->>'id'=v->>'packEntityId') and (v->>'entityId')::uuid<>(v->>'packEntityId')::uuid);
   perform rpg_private.assert(not exists(select 1 from public.rpg_entities e where e.id=(v->>'entityId')::uuid and e.campaign_id<>cid));
   perform rpg_private.assert(not exists(select 1 from rpg_private.world_foundations f,jsonb_array_elements(f.bindings) b,jsonb_array_elements(b->'mappings') m where f.campaign_id<>cid and m->>'entityId'=v->>'entityId'));
  end loop;
    perform rpg_private.assert(jsonb_array_length(snap->'bindings')<32 and not exists(select 1 from jsonb_array_elements(snap->'bindings') b where b->>'packId'=binding->>'packId' and b->>'id'<>binding->>'id'));
  perform rpg_private.assert(not exists(select 1 from jsonb_array_elements(snap->'bindings') b where b->>'id'=binding->>'id' and (b->>'packId'<>binding->>'packId' or b->'mappings'<>binding->'mappings' or b->>'packVersionId'=binding->>'packVersionId')));
  insert into rpg_private.world_foundations(campaign_id,bindings) values(cid,jsonb_build_array(binding)) on conflict(campaign_id) do update set bindings=(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(rpg_private.world_foundations.bindings) x where x->>'id'<>binding->>'id')||excluded.bindings,revision=rpg_private.world_foundations.revision+1;
 elsif p_action='configure' then
  perform rpg_private.fields(p_payload,array['command'],array['world','ruleset','executionPolicy']);
  perform rpg_private.assert(p_payload ?| array['world','ruleset','executionPolicy']);
  w:=case when p_payload?'world' then nullif(p_payload->'world','null') else nullif(snap->'world','null') end;
  if w is not null then perform rpg_private.world_validate_state(p_owner_id,cid,w,snap->'bindings'); perform rpg_private.assert(w->'warnings'=coalesce(nullif(snap#>'{world,warnings}','null'),'[]'::jsonb)); end if;
  if p_payload?'ruleset' then
   v:=p_payload->'ruleset'; perform rpg_private.fields(v,array['id','version','mode','validatorVersion']);
   perform rpg_private.assert(v->>'version'='1' and ((v->>'id'='console-basic-v1' and v->>'mode'='full_ruleset' and v->>'validatorVersion'='console-basic-v1') or (v->>'mode' in ('world_logic','custom_ruleset') and length(v->>'id') between 1 and 100 and length(v->>'validatorVersion') between 1 and 100)));
  end if;
  if p_payload?'executionPolicy' and p_payload->'executionPolicy'<>'null' then
   v:=p_payload->'executionPolicy'; perform rpg_private.fields(v,array['schemaVersion','revision','primary','taskOverrides']);
   perform rpg_private.assert(v->>'schemaVersion'='1' and (v->>'revision')::integer=coalesce((snap#>>'{executionPolicy,revision}')::integer,0)+1 and jsonb_typeof(v->'taskOverrides')='object');
  end if;
  insert into rpg_private.world_foundations(campaign_id,world,ruleset,execution_policy) values(cid,w,coalesce(p_payload->'ruleset',snap->'ruleset'),nullif(coalesce(p_payload->'executionPolicy',snap->'executionPolicy'),'null'))
  on conflict(campaign_id) do update set world=excluded.world,ruleset=excluded.ruleset,execution_policy=excluded.execution_policy,revision=rpg_private.world_foundations.revision+1;
 else raise exception 'rpg_validation'; end if;
 if p_action<>'stage' then update rpg_private.runtime_state set revision=revision+1 where campaign_id=cid; perform rpg_private.memory_invalidate(cid); result:=rpg_private.foundation_read(p_owner_id,cid); end if;
 insert into rpg_private.timeline_command_ids values('world',op,cid);
 insert into rpg_private.world_commands values(op,cid,jsonb_build_object('action',p_action,'payload',p_payload),result);
 return result;
end $$;
-- The private service seam is defense-in-depth; application parsers additionally validate full domain shapes.
create function rpg_private.world_validate_state(uid uuid,cid uuid,w jsonb,bindings jsonb) returns void language plpgsql stable set search_path='' as $$
#variable_conflict use_column
declare a jsonb; t jsonb; s jsonb; h jsonb; v text; sources jsonb; begin
 perform rpg_private.fields(w,array['schemaVersion','campaignId','policy','policyChangedAtWorldMinutes','actors','threads','hooks','warnings']);
 perform rpg_private.assert(w->>'schemaVersion'='1' and w->>'campaignId'=cid::text and octet_length(w::text)<=1048576);
 perform rpg_private.fields(w->'policy',array['simulation','autonomy','deadlinePressure']);
 perform rpg_private.assert(jsonb_typeof(w#>'{policy,simulation}')='boolean' and w#>>'{policy,autonomy}' in ('low','moderate','high') and w#>>'{policy,deadlinePressure}' in ('off','critical_only','normal'));
 perform rpg_private.assert((w->>'policyChangedAtWorldMinutes')::bigint>=0 and jsonb_array_length(w->'actors')<=500 and jsonb_array_length(w->'threads')<=300 and jsonb_array_length(w->'hooks')<=500 and jsonb_array_length(w->'warnings')<=500);
 select coalesce(jsonb_agg(distinct src.value),'[]') into sources from jsonb_array_elements(bindings) b,jsonb_array_elements(b->'sourceVersionIds') src(value);
 foreach v in array array['actors','threads','hooks'] loop
  perform rpg_private.assert(jsonb_typeof(w->v)='array' and (select count(*)=count(distinct value->>'id') from jsonb_array_elements(w->v)));
  perform rpg_private.assert(not exists(select 1 from jsonb_array_elements(w->v) x where x->>'campaignId'<>cid::text or (x->>'id')::uuid is null));
 end loop;
 for a in select value from jsonb_array_elements(w->'actors') loop
  perform rpg_private.assert(a->>'kind' in ('entity','group','faction','location') and a->>'control' in ('player','autonomous'));
  if a->>'entityId' is not null then
   perform rpg_private.assert(a->>'kind'='entity' and a->>'entityId'=a->>'id' and exists(select 1 from public.rpg_entities e where e.campaign_id=cid and e.id=(a->>'entityId')::uuid));
   if exists(select 1 from rpg_private.runtime_state r where r.campaign_id=cid and (r.configuration->'controlledEntityIds' ? (a->>'entityId') or exists(select 1 from public.rpg_entities pe where pe.campaign_id=cid and pe.id=(a->>'entityId')::uuid and pe.kind='player'))) then perform rpg_private.assert(a->>'control'='player'); end if;
  else perform rpg_private.assert(a->>'kind'<>'entity' and a->>'control'='autonomous'); end if;
  if a->>'locationId' is not null then perform rpg_private.assert(exists(select 1 from public.rpg_locations l where l.campaign_id=cid and l.id=(a->>'locationId')::uuid)); end if;
  perform rpg_private.library_evidence(uid,a->'knowledge',sources);
 end loop;
 for t in select value from jsonb_array_elements(w->'threads') loop
  perform rpg_private.uuid_array(t->'actorIds'); perform rpg_private.uuid_array(t->'decisionActorIds');
  perform rpg_private.assert(t->'actorIds'@>(t->'decisionActorIds'));
  for v in select jsonb_array_elements_text(t->'actorIds') loop perform rpg_private.assert(exists(select 1 from jsonb_array_elements(w->'actors') a where a->>'id'=v)); end loop;
  perform rpg_private.assert(not exists(select 1 from jsonb_array_elements(w->'actors') a where t->'decisionActorIds' ? (a->>'id') and (a->>'control'='player' or exists(select 1 from rpg_private.runtime_state r where r.campaign_id=cid and r.configuration->'controlledEntityIds' ? (a->>'entityId')))));
  for s in select value from jsonb_array_elements(t->'steps') loop
   perform rpg_private.library_evidence(uid,s->'evidence',sources);
   if s->'publicOutcome'<>'null' then perform rpg_private.library_evidence(uid,s#>'{publicOutcome,evidence}',sources,true); end if;
  end loop;
 end loop;
 for h in select value from jsonb_array_elements(w->'hooks') loop
  if h->'discovery'<>'null' then perform rpg_private.library_evidence(uid,h#>'{discovery,evidence}',sources,true); end if;
 end loop;
end $$;
create function rpg_private.world_event_id(op uuid,thread_id text,step_id text,audience text) returns uuid language plpgsql immutable set search_path='' as $$
declare h text; begin
 h:=substr(encode(sha256(convert_to('rpg-v1:'||op::text||':world-v1:'||thread_id||':'||step_id||':'||audience,'UTF8')),'hex'),1,32);
 h:=overlay(h placing '5' from 13 for 1); h:=overlay(h placing to_hex((get_byte(decode(substr(h,17,2),'hex'),0)>>4 & 3)|8) from 17 for 1);
 return h::uuid;
end $$;
create function rpg_private.world_validate_settlement(uid uuid,cid uuid,p jsonb,t rpg_private.turns) returns void language plpgsql stable set search_path='' as $$
#variable_conflict use_column
declare snap jsonb; e jsonb; a jsonb; oldw jsonb; neww jsonb; thread jsonb; changed jsonb; step jsonb; sources jsonb; n integer; idx integer; peer jsonb; hook jsonb; receipt jsonb; expected_warnings jsonb; begin
 perform rpg_private.fields(p,array['operationId','campaignId','timeline','expectedRevision','expectedRuntimeRevision','expectedHeadId','schemaVersion','status','fromWorldMinutes','throughWorldMinutes','sourceVersionIds','events','nextWorld']);
 snap:=rpg_private.foundation_fence(uid,cid,p); oldw:=snap->'world'; neww:=p->'nextWorld';
 perform rpg_private.assert(oldw<>'null' and p->>'schemaVersion'='1' and p->>'status'='staged' and p->>'operationId'=t.id::text and t.input->>'mode' in ('game','companion','mechanic'));
 perform rpg_private.assert(p->'fromWorldMinutes'=snap->'worldMinutes' and (p->>'throughWorldMinutes')::bigint between (p->>'fromWorldMinutes')::bigint and (p->>'fromWorldMinutes')::bigint+1440);
 perform rpg_private.uuid_array(p->'sourceVersionIds');
 select coalesce(jsonb_agg(distinct src.value),'[]') into sources from jsonb_array_elements(snap->'bindings') b,jsonb_array_elements(b->'sourceVersionIds') src(value);
 perform rpg_private.assert(sources@>(p->'sourceVersionIds') and (p->'sourceVersionIds')@>sources);
 perform rpg_private.world_validate_state(uid,cid,neww,snap->'bindings');
 perform rpg_private.assert(neww->'actors'=oldw->'actors' and (neww-array['threads','hooks','warnings'])=(oldw-array['threads','hooks','warnings']));
 perform rpg_private.assert(jsonb_array_length(neww->'threads')=jsonb_array_length(oldw->'threads') and jsonb_array_length(neww->'hooks')=jsonb_array_length(oldw->'hooks'));
 perform rpg_private.assert(jsonb_typeof(p->'events')='array' and jsonb_array_length(p->'events') between 1 and 8 and (select count(*)=count(distinct value->>'id') from jsonb_array_elements(p->'events')));
 for thread in select value from jsonb_array_elements(oldw->'threads') loop
  select value into changed from jsonb_array_elements(neww->'threads') where value->>'id'=thread->>'id';
  perform rpg_private.assert(changed is not null and (changed-array['cursor','revision','status'])=(thread-array['cursor','revision','status']) and (changed->>'cursor')::integer between (thread->>'cursor')::integer and jsonb_array_length(thread->'steps'));
  if changed<>thread then
   n:=(changed->>'cursor')::integer-(thread->>'cursor')::integer;
   perform rpg_private.assert(thread->>'status'='active' and n>0 and (changed->>'revision')::integer=(thread->>'revision')::integer+n and changed->>'status'=case when (changed->>'cursor')::integer=jsonb_array_length(thread->'steps') then 'resolved' else 'active' end);
   perform rpg_private.assert((select count(*) from jsonb_array_elements(p->'events') x where x->>'kind'='world.thread.advanced' and x->'threadIds'=jsonb_build_array(thread->>'id'))=n);
   for idx in (thread->>'cursor')::integer..(changed->>'cursor')::integer-1 loop
    perform rpg_private.assert((select count(*) from jsonb_array_elements(p->'events') x where x->>'kind'='world.thread.advanced' and x->'threadIds'=jsonb_build_array(thread->>'id') and (x#>>'{payload,previousCursor}')::integer=idx)=1);
   end loop;
  end if;
 end loop;
 for e in select value from jsonb_array_elements(p->'events') loop
  perform rpg_private.fields(e,array['schemaVersion','id','campaignId','originTimelineId','operationId','worldMinutes','kind','actorIds','threadIds','visibility','text','evidence','payload']);
  perform rpg_private.assert(e->>'schemaVersion'='1' and e->>'campaignId'=cid::text and e->>'operationId'=t.id::text and e->>'originTimelineId'=p#>>'{timeline,timelineId}' and (e->>'worldMinutes')::bigint between (p->>'fromWorldMinutes')::bigint and (p->>'throughWorldMinutes')::bigint and length(e->>'text') between 1 and 6000);
  perform rpg_private.assert(e->>'visibility' in ('public','private') and e->>'kind' in ('world.thread.advanced','world.observed'));
  perform rpg_private.uuid_array(e->'actorIds'); perform rpg_private.uuid_array(e->'threadIds');
  perform rpg_private.library_evidence(uid,e->'evidence',sources,e->>'visibility'='public');
  for a in select value from jsonb_array_elements(e->'actorIds') loop perform rpg_private.assert(exists(select 1 from jsonb_array_elements(oldw->'actors') x where x->'id'=a and (e->>'visibility'='private' or x->>'publicName' is not null))); end loop;
  if e->>'kind'='world.thread.advanced' then
   perform rpg_private.assert(e->>'visibility'='private' and jsonb_array_length(e->'threadIds')=1);
   select value into thread from jsonb_array_elements(oldw->'threads') where value->'id'=e->'threadIds'->0;
   perform rpg_private.assert(thread is not null and thread->'actorIds'=e->'actorIds');
   step:=thread->'steps'->(e#>>'{payload,previousCursor}')::integer;
   perform rpg_private.fields(e->'payload',array['schemaVersion','stepId','previousCursor','nextCursor','hookChanges']);
   perform rpg_private.assert(e#>>'{payload,schemaVersion}'='1' and e#>'{payload,hookChanges}'=step->'hookChanges');
   perform rpg_private.assert(e->>'id'=rpg_private.world_event_id(t.id,thread->>'id',step->>'id','private')::text);
   perform rpg_private.assert(not exists(select 1 from jsonb_array_elements(oldw->'actors') actor where thread->'decisionActorIds' ? (actor->>'id') and not (actor->'knowledge'@>(step->'evidence'))));
   perform rpg_private.assert(not exists(select 1 from jsonb_array_elements(step->'evidence') evidence join rpg_private.library_records old on old.version_id=(evidence->>'sourceVersionId')::uuid where exists(select 1 from rpg_private.library_records newer where newer.owner_id=old.owner_id and newer.kind=old.kind and newer.id=old.id and newer.version>old.version)));
   if step#>>'{trigger,kind}'='deadline' then
    perform rpg_private.assert(oldw#>>'{policy,simulation}'='true' and (step#>>'{trigger,atWorldMinutes}')::bigint<=(p->>'throughWorldMinutes')::bigint and (oldw#>>'{policy,deadlinePressure}'='normal' or (oldw#>>'{policy,deadlinePressure}'='critical_only' and step#>>'{trigger,scenarioCritical}'='true' and step#>>'{trigger,established}'='true')));
   elsif step#>>'{trigger,kind}'='autonomy' then
    perform rpg_private.assert(oldw#>>'{policy,simulation}'='true' and (step#>>'{trigger,atWorldMinutes}')::bigint<=(p->>'throughWorldMinutes')::bigint and array_position(array['local','related','broad'],step#>>'{trigger,scope}')<=array_position(array['low','moderate','high'],oldw#>>'{policy,autonomy}'));
    if oldw#>>'{policy,deadlinePressure}'<>'normal' then perform rpg_private.assert((e#>>'{payload,nextCursor}')::integer<jsonb_array_length(thread->'steps') and step->'hookChanges'='[]' and step->>'consequence'='background'); end if;
   elsif step#>>'{trigger,kind}'='causal' then
    perform rpg_private.assert(exists(select 1 from jsonb_array_elements(t.checkpoint#>'{resolution,changes}') ch where ch->>'family'=step#>>'{trigger,family}' and ch->>'id'=step#>>'{trigger,recordId}' and ch->'values'<>'{}'));
   else raise exception 'rpg_validation'; end if;
   if step->>'consequence'='surface_before_complete' then perform rpg_private.assert(exists(select 1 from jsonb_array_elements(oldw->'warnings') receipt where receipt->>'stepId'=step->>'id' and (receipt->>'opportunityUntilWorldMinutes')::bigint<=(p->>'fromWorldMinutes')::bigint and (receipt->>'atWorldMinutes')::bigint<(p->>'fromWorldMinutes')::bigint)); end if;
   perform rpg_private.assert(not exists(select 1 from jsonb_array_elements(step->'evidence') locator where locator->>'knowledge' in ('source','future_source')));
   perform rpg_private.assert(step->>'id'=e#>>'{payload,stepId}' and step->>'resolution'='deterministic' and (e#>>'{payload,nextCursor}')::integer=(e#>>'{payload,previousCursor}')::integer+1 and step->>'privateText'=e->>'text' and step->'evidence'=e->'evidence');
  else
   perform rpg_private.assert(e->>'visibility'='public' and e->'payload'='{}' and not exists(select 1 from jsonb_array_elements(e->'evidence') loc where loc->>'knowledge'<>'character'));
   perform rpg_private.assert(exists(select 1 from jsonb_array_elements(p->'events') priv,jsonb_array_elements(oldw->'threads') th,jsonb_array_elements(th->'steps') st
    where priv->>'kind'='world.thread.advanced' and priv->'threadIds'=jsonb_build_array(th->>'id') and priv#>>'{payload,stepId}'=st->>'id'
     and e->>'id'=rpg_private.world_event_id(t.id,th->>'id',st->>'id','public')::text and e->'worldMinutes'=priv->'worldMinutes'
     and e->'threadIds'=case when th->>'publicTitle' is null then '[]'::jsonb else jsonb_build_array(th->>'id') end
     and st#>>'{publicOutcome,text}'=e->>'text' and st#>'{publicOutcome,evidence}'=e->'evidence' and st#>'{publicOutcome,actorIds}'=e->'actorIds'));
  end if;
 end loop;
 -- A configured public consequence cannot be omitted while its private step commits.
 for e in select value from jsonb_array_elements(p->'events') where value->>'kind'='world.thread.advanced' loop
  select value into thread from jsonb_array_elements(oldw->'threads') where value->'id'=e->'threadIds'->0;
  step:=thread->'steps'->(e#>>'{payload,previousCursor}')::integer;
  if step->'publicOutcome'<>'null' then perform rpg_private.assert(exists(select 1 from jsonb_array_elements(p->'events') pub where pub->>'id'=rpg_private.world_event_id(t.id,thread->>'id',step->>'id','public')::text)); end if;
 end loop;
 for hook in select value from jsonb_array_elements(oldw->'hooks') loop
  select value into changed from jsonb_array_elements(neww->'hooks') where value->>'id'=hook->>'id';
  perform rpg_private.assert(changed is not null and changed-'status'=hook-'status');
  if changed->>'status'<>hook->>'status' then perform rpg_private.assert(hook->>'status' not in ('resolved','expired') and exists(select 1 from jsonb_array_elements(p->'events') ev,jsonb_array_elements(ev#>'{payload,hookChanges}') ch where ch->>'hookId'=hook->>'id' and ch->>'status'=changed->>'status')); end if;
 end loop;
 expected_warnings:=oldw->'warnings';
 for e in select value from jsonb_array_elements(p->'events') where value->>'kind'='world.thread.advanced' loop
  select value into thread from jsonb_array_elements(oldw->'threads') where value->'id'=e->'threadIds'->0;
  step:=thread->'steps'->(e#>>'{payload,previousCursor}')::integer;
  if step->'warning'<>'null' then
   expected_warnings:=expected_warnings||jsonb_build_array(jsonb_build_object('stepId',step#>'{warning,forStepId}','eventId',rpg_private.world_event_id(t.id,thread->>'id',step->>'id','public'),'atWorldMinutes',e->'worldMinutes','opportunityUntilWorldMinutes',(e->>'worldMinutes')::bigint+(step#>>'{warning,opportunityMinutes}')::bigint,'recipientActorIds',step#>'{warning,recipientActorIds}'));
  end if;
 end loop;
 perform rpg_private.assert(neww->'warnings'=expected_warnings);
end $$;
-- Add optional staged-world packet fields to the accepted validator (all old fields remain required).
do $$ declare d text; begin
 select pg_get_functiondef('public.rpg_runtime_phase2(uuid,uuid,text,jsonb)'::regprocedure) into d;
 d:=replace(d,'array[''plan'',''checks'',''resolution'',''narration'',''feedback'',''usage'']','array[''plan'',''checks'',''resolution'',''narration'',''feedback'',''usage''],array[''worldSettlement'']');
 d:=replace(d,'array[''narration'',''visualDescription'',''resolution'',''privatePatches'',''checks'',''guidanceProposal'']','array[''narration'',''visualDescription'',''resolution'',''privatePatches'',''checks'',''guidanceProposal''],array[''worldSettlement'']');
 execute d;
end $$;
alter function public.rpg_runtime(uuid,uuid,text,jsonb,jsonb) set schema rpg_private;
alter function rpg_private.rpg_runtime(uuid,uuid,text,jsonb,jsonb) rename to runtime_before_wave1;
create function public.rpg_runtime(p_owner_id uuid,p_campaign_id uuid,p_action text,p_payload jsonb default '{}',p_timeline jsonb default null) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare result jsonb; t rpg_private.turns%rowtype; p jsonb; staged jsonb; e jsonb; eid uuid; sid uuid; begin
 if p_owner_id is null or not exists(select 1 from rpg_private.owner_registry where user_id=p_owner_id) then raise exception 'rpg_forbidden' using errcode='42501'; end if;
 perform 1 from public.rpg_campaigns where id=p_campaign_id for update; if not found then raise exception 'rpg_not_found'; end if;
 perform rpg_private.timeline_assert(p_campaign_id,p_timeline,p_action not in ('play','get'));
 select * into t from rpg_private.turns where campaign_id=p_campaign_id and id=(p_payload->>'operationId')::uuid;
 if p_action='checkpoint' and p_payload#>'{checkpoint,worldSettlement}' is not null and p_payload#>'{checkpoint,worldSettlement}'<>'null' then
  select settlement into staged from rpg_private.world_stages where campaign_id=p_campaign_id and id=t.id;
  perform rpg_private.assert(staged is not null and staged=p_payload#>'{checkpoint,worldSettlement}');
 end if;
 if p_action='commit' and t.status<>'committed' then
  p:=nullif(p_payload#>'{packet,worldSettlement}','null');
  select settlement into staged from rpg_private.world_stages where campaign_id=p_campaign_id and id=t.id;
  if staged is not null or p is not null then
   perform rpg_private.assert(p is not null and p=staged and p=t.checkpoint->'worldSettlement' and p->'throughWorldMinutes'=p_payload#>'{packet,resolution,worldMinutes}');
   if t.lease_token is distinct from (p_payload->>'token')::uuid or t.lease_until<=now() or t.status<>'generating' then raise exception 'rpg_conflict'; end if;
   perform rpg_private.world_validate_settlement(p_owner_id,p_campaign_id,p,t);
   -- These writes and the original gameplay commit/autosave are ONE SQL transaction.
   update rpg_private.world_foundations set world=p->'nextWorld',revision=revision+1 where campaign_id=p_campaign_id;
   for e in select value from jsonb_array_elements(p->'events') loop
    eid:=(e->>'id')::uuid;
    insert into rpg_private.world_events(id,campaign_id,operation_id,event) values(eid,p_campaign_id,t.id,e);
    -- Reuse existing Memory authority. No actor-involvement => witness inference.
    perform rpg_private.memory_index(p_campaign_id,case when e->>'visibility'='public' then 'event' else 'private_event' end,eid,'1',e->>'text',e->>'visibility',t.session_id,'{}','{}','history','record');
   end loop;
  end if;
 end if;
 result:=rpg_private.runtime_before_wave1(p_owner_id,p_campaign_id,p_action,p_payload,p_timeline);
 return result;
end $$;
-- Durable per-operation choices; all DM stages pin together before the first provider call.
create function public.rpg_execution_profile(p_owner_id uuid,p_campaign_id uuid,p_operation_id uuid,p_profiles jsonb,p_timeline jsonb,p_token uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare result jsonb; p jsonb; t rpg_private.turns%rowtype; j rpg_private.memory_jobs%rowtype; task text; begin
 if p_owner_id is null or not exists(select 1 from rpg_private.owner_registry where user_id=p_owner_id) then raise exception 'rpg_forbidden' using errcode='42501'; end if;
 perform 1 from public.rpg_campaigns where id=p_campaign_id for update; if not found then raise exception 'rpg_not_found'; end if;
 perform rpg_private.timeline_assert(p_campaign_id,p_timeline);
 select coalesce(jsonb_object_agg(e.task,e.profile),'{}') into result from rpg_private.execution_profiles e where e.campaign_id=p_campaign_id and e.operation_id=p_operation_id;
 if result<>'{}' then return result; end if;
 if p_profiles is null then return '{}'::jsonb; end if;
 select * into t from rpg_private.turns where campaign_id=p_campaign_id and id=p_operation_id;
 if found then
  perform rpg_private.assert((t.status in ('pending','generating','awaiting_confirmation') or (t.status='failed' and t.retryable)) and t.lease_until>now() and t.expected_revision=(select revision from rpg_private.runtime_state where campaign_id=p_campaign_id));
  if t.input->>'mode' in ('feedback','ooc') then perform rpg_private.fields(p_profiles,array['dm.feedback']); else perform rpg_private.fields(p_profiles,array['dm.plan','dm.narrate']); end if;
 else
  select * into j from rpg_private.memory_jobs where campaign_id=p_campaign_id and id=p_operation_id;
  perform rpg_private.assert(j.id is not null and j.token=p_token and j.status='generating' and j.lease_until>now());
  perform rpg_private.fields(p_profiles,array['memory.summary']);
 end if;
 for task,p in select key,value from jsonb_each(p_profiles) loop
  perform rpg_private.fields(p,array['schemaVersion','id','policyRevision','registryVersion','task','providerId','modelId','reasoning']);
  perform rpg_private.assert(p->>'schemaVersion'='1' and p->>'task'=task and p->>'providerId'='openai' and p->>'modelId' in ('gpt-6-astra','gpt-5.4','gpt-5.4-mini') and (p->>'policyRevision')::integer>=0 and length(p->>'registryVersion') between 1 and 100);
  insert into rpg_private.execution_profiles values((p->>'id')::uuid,p_campaign_id,p_operation_id,task,p);
 end loop;
 return p_profiles;
end $$;
-- Original Events remain immutable; source-linked derivatives are invalidated, including on old-save load.
create function rpg_private.world_invalidate_derivatives(cid uuid) returns void language plpgsql set search_path='' as $$
declare ids uuid[]; begin
 select array_agg(distinct w.id) into ids from rpg_private.world_events w,jsonb_array_elements(w.event->'evidence') ev
 join rpg_private.library_records old on old.version_id=(ev->>'sourceVersionId')::uuid
 where w.campaign_id=cid and exists(select 1 from rpg_private.library_records newer where newer.owner_id=old.owner_id and newer.kind=old.kind and newer.id=old.id and newer.version>old.version);
 if coalesce(cardinality(ids),0)>0 then
  update rpg_private.memory_public_sources set current=false,status='invalid' where campaign_id=cid and kind in ('event','private_event') and source_id=any(ids);
  update rpg_private.memory_private_sources set current=false,status='invalid' where campaign_id=cid and kind in ('event','private_event') and source_id=any(ids);
  perform rpg_private.memory_invalidate(cid);
 end if;
end $$;
alter function rpg_private.timeline_activate(uuid,uuid,uuid) rename to timeline_activate_before_wave1;
create function rpg_private.timeline_activate(cid uuid,mid uuid,target uuid) returns void language plpgsql set search_path='' as $$
begin perform rpg_private.timeline_activate_before_wave1(cid,mid,target); perform rpg_private.world_invalidate_derivatives(cid); end $$;
revoke all on all tables in schema rpg_private from public,anon,authenticated;
revoke all on all functions in schema rpg_private from public,anon,authenticated;
revoke all on function public.rpg_library(uuid,uuid,text,jsonb,jsonb) from public,anon,authenticated;
revoke all on function public.rpg_world(uuid,uuid,text,jsonb,jsonb) from public,anon,authenticated;
revoke all on function public.rpg_runtime(uuid,uuid,text,jsonb,jsonb) from public,anon,authenticated;
revoke all on function public.rpg_execution_profile(uuid,uuid,uuid,jsonb,jsonb,uuid) from public,anon,authenticated;
do $$ begin if exists(select 1 from pg_roles where rolname='service_role') then
revoke all on all functions in schema rpg_private from service_role;
grant execute on function public.rpg_library(uuid,uuid,text,jsonb,jsonb) to service_role;
grant execute on function public.rpg_world(uuid,uuid,text,jsonb,jsonb) to service_role;
grant execute on function public.rpg_runtime(uuid,uuid,text,jsonb,jsonb) to service_role;
grant execute on function public.rpg_execution_profile(uuid,uuid,uuid,jsonb,jsonb,uuid) to service_role;
end if; end $$;
commit;
